// Lazy chunk loader: each "import()" is loaded once, cached, and retried on failure.
let attemptsByChunk = {};
function fakeImport(name) {
  // Simulates a network fetch; the admin chunk fails on its first try (stale deploy).
  attemptsByChunk[name] = (attemptsByChunk[name] || 0) + 1;
  if (name === 'admin' && attemptsByChunk[name] === 1) {
    return Promise.reject(new Error('ChunkLoadError: admin'));
  }
  return Promise.resolve({ name, loadedOnAttempt: attemptsByChunk[name] });
}
const cache = new Map();
function loadChunk(name, retries = 1) {
  if (cache.has(name)) return cache.get(name); // second visit: no network
  const p = fakeImport(name).catch(err => {
    cache.delete(name); // never cache a failure
    if (retries > 0) return loadChunk(name, retries - 1);
    throw err;
  });
  cache.set(name, p);
  return p;
}
async function main() {
  console.log('initial bundle: shell only');
  for (const route of ['reports', 'admin', 'reports']) {
    const m = await loadChunk(route);
    console.log('navigate /' + route + ' -> chunk', m.name,
      'attempt', m.loadedOnAttempt, 'total fetches', attemptsByChunk[route]);
  }
}
main();

// canMatch lets two routes share one path; first route whose guard passes wins.
const routes = [
  { path: 'dashboard', canMatch: u => u.role === 'admin', name: 'AdminDashboard' },
  { path: 'dashboard', canMatch: u => u.role === 'user', name: 'UserDashboard' },
  { path: 'settings', canActivate: u => u.loggedIn, name: 'Settings' },
];
function navigate(url, user) {
  for (const r of routes) {
    if (r.path !== url) continue;
    if (r.canMatch && !r.canMatch(user)) continue; // not matched: try next route
    if (r.canActivate && !r.canActivate(user)) {
      // a guard "redirects" by returning a UrlTree instead of false
      return 'redirect -> /login?returnUrl=/' + url;
    }
    return 'render ' + r.name;
  }
  return 'no route matched';
}
