// Async validator with a timer-as-debounce: a newer value cancels the older pending check.
const taken = new Set(['alice', 'bob']);
let serverCalls = 0;
function makeControl() {
  let timer = null, status = 'VALID', token = 0;
  return {
    setValue(v) {
      clearTimeout(timer);           // Angular unsubscribes the previous run; same effect
      const my = ++token;
      status = 'PENDING';
      timer = setTimeout(() => {     // wait 50 ms of quiet before hitting the server
        serverCalls++;
        setTimeout(() => {           // fake HTTP latency
          if (my !== token) return;  // stale answer, ignore
          status = taken.has(v) ? 'INVALID usernameTaken' : 'VALID';
          console.log('"' + v + '" ->', status);
        }, 10);
      }, 50);
    },
    get status() { return status; },
  };
}
