// OnPush skips a child unless its input REFERENCE changed.
function makeOnPushChild(name) {
  let lastInput = undefined, renders = 0;
  return {
    check(input) {
      if (input === lastInput) return;   // same reference: skipped
      lastInput = input; renders++;
      console.log(name, 'rendered with', JSON.stringify(input));
    },
    get renders() { return renders; },
  };
}
