// switchMap idea: only the latest search may update state; older replies are dropped.
const state = { loading: false, results: [], searches: 0 };
function api(q, ms) {
  return new Promise(res => setTimeout(() => res([q + '-1', q + '-2']), ms));
}
let latest = 0;
function search(q, latency) {
  const id = ++latest;              // identifies this request
  state.loading = true; state.searches++;
  console.log('dispatch search "' + q + '"');
  api(q, latency).then(r => {
    if (id !== latest) {            // newer search exists: cancelled, like switchMap
      console.log('  dropped stale reply for "' + q + '"');
      return;
    }
    state.loading = false; state.results = r;
    console.log('  success for "' + q + '":', r.join(', '));
  }).catch(() => { state.loading = false; });
}
search('ang', 80);   // slow request
search('angular', 20); // fast, newer request wins
setTimeout(() => console.log('final state:', JSON.stringify(state)), 200);

// Core of the users table: filter -> sort -> paginate as pure functions.
const users = [
  { id: 1, name: 'Zoe' }, { id: 2, name: 'adam' }, { id: 3, name: 'Mia' },
  { id: 4, name: 'Adrian' }, { id: 5, name: 'Noah' }, { id: 6, name: 'Ada' },
];
function view(all, query, dir, page, size) {
  const q = query.toLowerCase();
  const filtered = all.filter(u => u.name.toLowerCase().includes(q)); // like computed()
  const sorted = [...filtered].sort((a, b) =>                          // copy: never mutate input
    dir * a.name.toLowerCase().localeCompare(b.name.toLowerCase()));
  const pages = Math.max(1, Math.ceil(sorted.length / size));
  const p = Math.min(page, pages);                                     // clamp page after filtering
  return { pages, page: p, rows: sorted.slice((p - 1) * size, p * size).map(u => u.name) };
}
